/**
 * SignalDesk board for Hermes Desktop.
 * Only imports @hermes/plugin-sdk, react, and react/jsx-runtime.
 * GENERATED by scripts/build_desktop.py from scripts/desktop-src/ (board.js + map.js)
 * with OpenLayers 10.5.0 (BSD-2-Clause) bundled inline for the LocalLead Map.
 * Untested inside a live Desktop window on the build box — validate
 * still has to pass the desktop surface check.
 */

import {
  Badge,
  Button,
  ROUTES_AREA,
  SIDEBAR_NAV_AREA,
  PALETTE_AREA,
  ScrollArea,
  cn,
  host,
  useMutation,
  useQuery,
  useQueryClient
} from '@hermes/plugin-sdk'
import { jsx, jsxs } from 'react/jsx-runtime'
import { useEffect, useMemo, useRef, useState } from 'react'

/*__OL_BUNDLE__*/

/*__MAP_PANEL__*/

const ID = 'signaldesk'
const STAGES = ['new', 'qualified', 'drafted', 'approved', 'sent', 'replied', 'won', 'lost']
const STAGE_LABELS = {
  new: 'New',
  qualified: 'Qualified',
  drafted: 'Drafted',
  approved: 'Approved',
  sent: 'Sent',
  replied: 'Replied',
  won: 'Won',
  lost: 'Lost'
}

function scoreClass(score) {
  if (score >= 60) return 'high'
  if (score >= 35) return 'mid'
  return 'low'
}

function scoreColor(score) {
  if (score >= 60) return 'var(--ui-success, #3ee0a4)'
  if (score >= 35) return 'var(--ui-warning, #fbbf24)'
  return 'var(--ui-danger, #fb7185)'
}

function BoardPage(props) {
  const ctx = props.ctx
  const qc = useQueryClient()
  const [selectedId, setSelectedId] = useState(null)
  const [query, setQuery] = useState('')
  const [signal, setSignal] = useState('all')
  const [minScore, setMinScore] = useState(0)
  const [view, setView] = useState('board')

  const stateQuery = useQuery({
    queryKey: [ctx.source, 'state'],
    queryFn: () => ctx.rest('/state'),
    refetchInterval: 8000
  })

  const data = stateQuery.data || { leads: [], counts: {}, icp: {}, sources: [], stages: STAGES }
  const leads = data.leads || []

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase()
    return leads.filter((lead) => {
      if (signal !== 'all' && lead.signal_type !== signal) return false
      if ((lead.score || 0) < minScore) return false
      if (!q) return true
      const blob = [lead.company, lead.role, lead.location, lead.domain, lead.signal_quote, lead.contact]
        .join(' ')
        .toLowerCase()
      return blob.includes(q)
    })
  }, [leads, query, signal, minScore])

  const selected = leads.find((l) => l.id === selectedId) || null

  const mutate = useMutation({
    mutationFn: async (input) => ctx.rest(input.path, { method: 'POST', body: input.body }),
    onSuccess: async () => {
      await qc.invalidateQueries({ queryKey: [ctx.source, 'state'] })
    },
    onError: (err) => {
      host.notify({ kind: 'error', message: (err && err.message) || 'SignalDesk request failed' })
    }
  })

  const act = (path, body, okMessage) => {
    mutate.mutate(
      { path, body },
      {
        onSuccess: (res) => {
          if (okMessage) host.notify({ kind: 'success', message: okMessage })
          if (res && res.eml_path && ctx.os && ctx.os.revealPath) {
            ctx.os.revealPath(res.eml_path)
          }
        }
      }
    )
  }

  const copyDraft = async (lead) => {
    const text = (lead.draft_subject ? lead.draft_subject + '\n\n' : '') + (lead.draft_body || '')
    const ok = ctx.os && ctx.os.writeClipboard ? await ctx.os.writeClipboard(text) : false
    host.notify({ kind: ok ? 'success' : 'error', message: ok ? 'Draft copied' : 'Could not write the clipboard' })
  }

  const openSource = (url) => {
    if (url && ctx.os && ctx.os.openExternal) ctx.os.openExternal(url)
  }

  const counts = data.counts || {}
  const total = Object.values(counts).reduce((a, b) => a + (b || 0), 0)
  const icp = data.icp || {}
  const sources = data.sources || []

  return jsxs('div', {
    className: 'flex h-full min-h-0 flex-col gap-2 p-3 text-sm',
    children: [
      jsxs('div', {
        className: 'flex flex-wrap items-start justify-between gap-3',
        children: [
          jsxs('div', {
            children: [
              jsx('div', { className: 'text-base font-semibold', children: 'SignalDesk' }),
              jsx('div', {
                className: 'text-(--ui-text-tertiary)',
                children: icp.offer || 'Set an ICP, then scan public hiring and launch signals.'
              })
            ]
          }),
          jsxs('div', {
            className: 'flex gap-3 text-(--ui-text-tertiary)',
            children: [
              jsxs('span', { children: [jsx('strong', { className: 'text-foreground', children: total }), ' leads'] }),
              jsxs('span', { children: [jsx('strong', { className: 'text-foreground', children: counts.approved || 0 }), ' approved'] })
            ]
          })
        ]
      }),
      jsxs('div', {
        className: 'flex flex-wrap items-center gap-2',
        children: [
          ...(sources.map((src) =>
            jsxs('span', {
              className: 'inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] text-(--ui-text-tertiary)',
              children: [
                src.name,
                jsx(Badge, {
                  variant: 'secondary',
                  className: 'text-[9px] uppercase',
                  children: src.key_required ? 'key' : 'no key'
                })
              ]
            }, src.id)
          ) || []),
          jsx(Button, {
            size: 'sm',
            variant: view === 'board' ? 'default' : 'secondary',
            onClick: () => setView('board'),
            children: 'Pipeline'
          }),
          jsx(Button, {
            size: 'sm',
            variant: view === 'map' ? 'default' : 'secondary',
            onClick: () => setView('map'),
            children: 'Map'
          }),
          jsx('input', {
            className: 'h-7 rounded-md border bg-transparent px-2 text-xs',
            placeholder: 'Filter companies…',
            value: query,
            onChange: (e) => setQuery(e.target.value)
          }),
          jsxs('select', {
            className: 'h-7 rounded-md border bg-transparent px-2 text-xs',
            value: signal,
            onChange: (e) => setSignal(e.target.value),
            children: [
              jsx('option', { value: 'all', children: 'All signals' }),
              jsx('option', { value: 'hiring', children: 'Hiring' }),
              jsx('option', { value: 'launch', children: 'Launches' }),
              jsx('option', { value: 'local', children: 'Local (map)' })
            ]
          }),
          jsxs('label', {
            className: 'flex items-center gap-1 text-[11px] text-(--ui-text-tertiary)',
            children: [
              'Min score',
              jsx('input', {
                type: 'range',
                min: 0,
                max: 80,
                step: 5,
                value: minScore,
                onChange: (e) => setMinScore(Number(e.target.value) || 0)
              }),
              String(minScore)
            ]
          })
        ]
      }),
      stateQuery.isError
        ? jsx('div', {
            className: 'rounded-md border p-3 text-(--ui-text-tertiary)',
            children:
              'Could not load the board. Enable the SignalDesk plugin in this profile so /api/plugins/signaldesk is mounted, then Rescan desktop plugins. This Desktop page was not exercised in a live Desktop window on the build machine.'
          })
        : jsxs('div', {
            className: 'flex min-h-0 flex-1 gap-2',
            children: [
              view === 'map'
                ? jsx(MapPanel, { ctx, leads: visible, selectedId, onSelect: setSelectedId })
                : null,
              view === 'map' ? null : jsx('div', {
                className: 'flex min-h-0 flex-1 gap-2 overflow-x-auto',
                children: STAGES.map((stage) => {
                  const items = visible
                    .filter((l) => l.stage === stage)
                    .slice()
                    .sort((a, b) => (b.score || 0) - (a.score || 0))
                  return jsxs(
                    'section',
                    {
                      className: 'flex w-[220px] shrink-0 flex-col rounded-xl border',
                      children: [
                        jsxs('h2', {
                          className: 'flex items-center justify-between px-2 py-2 text-[11px] uppercase tracking-wide text-(--ui-text-tertiary)',
                          children: [STAGE_LABELS[stage], jsx('span', { children: items.length })]
                        }),
                        jsx(ScrollArea, {
                          className: 'min-h-0 flex-1 px-1 pb-2',
                          children: items.length
                            ? items.map((lead) =>
                                jsxs(
                                  'button',
                                  {
                                    type: 'button',
                                    onClick: () => setSelectedId(lead.id),
                                    className: cn(
                                      'mb-2 w-full rounded-lg border p-2 text-left',
                                      selectedId === lead.id ? 'border-[color:var(--ui-success,#3ee0a4)]' : ''
                                    ),
                                    children: [
                                      jsxs('div', {
                                        className: 'flex items-start justify-between gap-2',
                                        children: [
                                          jsx('div', { className: 'font-medium', children: lead.company }),
                                          jsx('span', {
                                            className: 'rounded-full px-1.5 text-[11px] font-semibold',
                                            style: { color: scoreColor(lead.score) },
                                            children: lead.score
                                          })
                                        ]
                                      }),
                                      jsx('div', {
                                        className: 'mt-1 text-[10px] uppercase tracking-wide text-(--ui-text-tertiary)',
                                        children: lead.signal_type
                                      }),
                                      jsx('p', {
                                        className: 'mt-1 line-clamp-3 text-xs text-(--ui-text-secondary)',
                                        children: lead.signal_quote || ''
                                      })
                                    ]
                                  },
                                  lead.id
                                )
                              )
                            : jsx('p', { className: 'px-2 text-xs text-(--ui-text-tertiary)', children: 'No leads' })
                        })
                      ]
                    },
                    stage
                  )
                })
              }),
              selected
                ? jsxs('aside', {
                    className: 'flex w-[360px] shrink-0 flex-col overflow-hidden rounded-xl border p-3',
                    children: [
                      jsxs('div', {
                        className: 'flex items-start justify-between gap-2',
                        children: [
                          jsxs('div', {
                            children: [
                              jsx('div', {
                                className: 'text-[10px] uppercase tracking-wide text-(--ui-text-tertiary)',
                                children: (selected.signal_type || '') + ' · ' + (selected.stage || '')
                              }),
                              jsx('h2', { className: 'text-lg font-semibold', children: selected.company }),
                              selected.role
                                ? jsx('div', { className: 'text-xs text-(--ui-text-tertiary)', children: selected.role })
                                : null,
                              selected.contact
                                ? jsx('div', { className: 'text-xs text-(--ui-text-tertiary)', children: selected.contact })
                                : null
                            ]
                          }),
                          jsx('span', {
                            className: 'rounded-full px-2 py-1 text-sm font-semibold',
                            style: { color: scoreColor(selected.score) },
                            children: selected.score
                          })
                        ]
                      }),
                      jsx(ScrollArea, {
                        className: 'min-h-0 flex-1 py-2',
                        children: jsxs('div', {
                          className: 'flex flex-col gap-3',
                          children: [
                            jsxs('section', {
                              children: [
                                jsx('h3', { className: 'text-[11px] uppercase tracking-wide text-(--ui-text-tertiary)', children: 'Signal' }),
                                jsx('p', { className: 'text-xs', children: selected.signal_quote || '' }),
                                selected.source_url
                                  ? jsx(Button, {
                                      variant: 'ghost',
                                      size: 'sm',
                                      className: 'mt-1 px-0',
                                      onClick: () => openSource(selected.source_url),
                                      children: selected.signal_type === 'local' ? 'Open on OpenStreetMap' : 'Open source'
                                    })
                                  : null
                              ]
                            }),
                            selected.signal_type === 'local'
                              ? jsxs('section', {
                                  children: [
                                    jsx('h3', { className: 'text-[11px] uppercase tracking-wide text-(--ui-text-tertiary)', children: 'OpenStreetMap details' }),
                                    ...['business_type', 'address', 'website', 'phone', 'opening_hours']
                                      .filter((k) => selected.provenance && selected.provenance[k])
                                      .map((k) => jsx('div', { className: 'text-xs', children: k.replace('_', ' ') + ': ' + selected.provenance[k] }, k)),
                                    jsx('div', { className: 'mt-1 text-[11px] text-(--ui-text-tertiary)', children: '© OpenStreetMap contributors, ODbL' })
                                  ]
                                })
                              : null,
                            jsxs('section', {
                              children: [
                                jsx('h3', { className: 'text-[11px] uppercase tracking-wide text-(--ui-text-tertiary)', children: 'Why this score' }),
                                jsx('ul', {
                                  className: 'list-disc pl-4 text-xs text-(--ui-text-tertiary)',
                                  children: (selected.score_reasons || []).map((reason, i) =>
                                    jsx('li', { children: reason }, i)
                                  )
                                })
                              ]
                            }),
                            jsxs('section', {
                              children: [
                                jsx('h3', { className: 'text-[11px] uppercase tracking-wide text-(--ui-text-tertiary)', children: 'Draft' }),
                                selected.draft_body
                                  ? jsxs('div', {
                                      className: 'rounded-md border p-2',
                                      children: [
                                        jsx('div', { className: 'text-xs font-medium', children: selected.draft_subject }),
                                        jsx('pre', {
                                          className: 'mt-1 whitespace-pre-wrap font-mono text-xs',
                                          children: selected.draft_body
                                        })
                                      ]
                                    })
                                  : jsx('p', { className: 'text-xs text-(--ui-text-tertiary)', children: 'No draft yet.' })
                              ]
                            })
                          ]
                        })
                      }),
                      jsxs('div', {
                        className: 'flex flex-wrap gap-2 pt-2',
                        children: [
                          !selected.draft_body
                            ? jsx(Button, {
                                size: 'sm',
                                onClick: () => act('/leads/draft', { lead_id: selected.id }, 'Draft written'),
                                children: 'Draft'
                              })
                            : null,
                          selected.draft_body && selected.stage !== 'approved' && selected.stage !== 'sent' && selected.stage !== 'won'
                            ? jsx(Button, {
                                size: 'sm',
                                onClick: () => act('/leads/approve', { lead_id: selected.id }, 'Approved. Still not sent.'),
                                children: 'Approve'
                              })
                            : null,
                          selected.draft_body
                            ? jsx(Button, {
                                size: 'sm',
                                variant: 'secondary',
                                onClick: () => copyDraft(selected),
                                children: 'Copy'
                              })
                            : null,
                          selected.draft_body
                            ? jsx(Button, {
                                size: 'sm',
                                variant: 'secondary',
                                onClick: () =>
                                  act('/leads/prepare', { lead_id: selected.id }, 'Wrote a local .eml — nothing was sent'),
                                children: 'Open .eml'
                              })
                            : null,
                          selected.stage !== 'lost' && selected.stage !== 'won'
                            ? jsx(Button, {
                                size: 'sm',
                                variant: 'ghost',
                                onClick: () => act('/leads/mark', { lead_id: selected.id, stage: 'lost' }, 'Marked lost'),
                                children: 'Reject'
                              })
                            : null
                        ]
                      })
                    ]
                  })
                : null
            ]
          })
    ]
  })
}

export default {
  id: ID,
  name: 'SignalDesk',
  defaultEnabled: true,
  register(ctx) {
    ctx.registerMany([
      {
        id: 'page',
        area: ROUTES_AREA,
        data: { path: '/signaldesk' },
        render: () => jsx(BoardPage, { ctx })
      },
      {
        id: 'nav',
        area: SIDEBAR_NAV_AREA,
        data: { path: '/signaldesk', label: 'SignalDesk', codicon: 'organization' }
      },
      {
        id: 'open',
        area: PALETTE_AREA,
        title: 'Open SignalDesk board',
        data: { action: () => host.navigate('/signaldesk') }
      }
    ])
  }
}
